/** Corrections append decisions; source rows and previous evidence are never deleted. */
final class Operations {
 static function changed(\PDO $db,string $kind,array $before,array $after,int $resource,?array $actor):void {
  $fields=['omc'=>['client','invoice_date','amount_cents','observation','comisionar','workplace'],'fan'=>['recipient','awb_date','cash_due_cents','content','service_type'],'netopia'=>['client','operation_date','gross_amount_cents','commission','vat'],'site'=>['client','company','order_date','amount_cents','awb','payment_method']][$kind];$diff=[];
  foreach($fields as $k){if(in_array($k,['comisionar','workplace'],true)){$oldSite=label((string)($before['comisionar']??''))==='SITE GOLDENDRINKS'||label((string)($before['workplace']??''))==='SITE';$newSite=label((string)($after['comisionar']??''))==='SITE GOLDENDRINKS'||label((string)($after['workplace']??''))==='SITE';if(!$oldSite||$newSite)continue;}$a=$before[$k]??null;$b=$after[$k]??null;if(in_array($k,['client','recipient','company'],true)){$a=nameKey((string)$a);$b=nameKey((string)$b);}elseif(in_array($k,['commission','vat'],true)){$a=Sources::fixed($a,5);$b=Sources::fixed($b,5);}if(($a===null)!==($b===null)||(string)$a!==(string)$b)$diff[$k]=['before'=>$before[$k]??null,'after'=>$after[$k]??null];}
  if(!$diff)return;$table=['omc'=>'invoices','fan'=>'shipment_assignments','netopia'=>'payment_resolutions','site'=>'invoice_orders'][$kind];$col=['omc'=>'id','fan'=>'shipment_id','netopia'=>'payment_id','site'=>'order_id'][$kind];if($kind==='netopia')$table=Topups::links();$invoice=$kind==='omc'?$resource:(one($db,'SELECT invoice_id FROM '.$table.' WHERE '.$col.'=?',[$resource])['invoice_id']??null);if(!$invoice)return;
  $linked=$kind!=='omc'||one($db,'SELECT invoice_id FROM invoice_orders WHERE invoice_id=?',[$invoice])||one($db,'SELECT invoice_id FROM shipment_assignments WHERE invoice_id=?',[$invoice])||one($db,'SELECT invoice_id FROM payment_resolutions WHERE invoice_id=?',[$invoice]);if(!$linked)return;
  $targets=['invoice'=>$invoice];if($kind!=='omc')$targets[['fan'=>'shipment','netopia'=>'payment','site'=>'order'][$kind]]=$resource;$key='changed:'.hash('sha256',$kind.':'.$resource.':'.$after['source_hash']);if(one($db,'SELECT id FROM decisions WHERE idempotency_key=?',[$key]))return;
  $did=decision($db,'source_changed',$targets,['kind'=>$kind,'resource'=>$resource,'before_hash'=>$before['source_hash'],'resource_hash'=>$after['source_hash'],'changes'=>$diff],'Sursa asociată a fost actualizată; verifică diferențele fără mutarea legăturii.',$actor,$key);audit($db,'linked_source_changed',['kind'=>$kind,'resource'=>$resource,'invoice'=>$invoice],$actor,$did);
 }
 static function alerts(\PDO $db,int $invoice):array {return array_map(function($r){$r['proof']=json_decode($r['source_hashes_json'],true);unset($r['source_hashes_json']);return $r;},query($db,"SELECT id,reason,source_hashes_json,created_at FROM decisions WHERE invoice_id=? AND action='source_changed' AND active=1 ORDER BY id",[$invoice])->fetchAll());}
 static function acknowledge(\PDO $db,array $in,array $actor):array {permit($actor,'operate');$reason=self::reason($in);return transaction($db,function()use($db,$in,$actor,$reason){$d=one($db,"SELECT * FROM decisions WHERE id=? AND action='source_changed' AND active=1 FOR UPDATE",[(int)$in['id']]);if(!$d)throw new Problem('Verificarea nu mai este activă.',409);$proof=json_decode($d['source_hashes_json'],true);$r=one($db,'SELECT * FROM '.Store::TABLE[$proof['kind']].' WHERE id=? FOR UPDATE',[$proof['resource']]);$i=one($db,"SELECT id,source_hash,amount_cents FROM invoices WHERE id=? AND scope<>'internal'",[$d['invoice_id']]);if(!$i||!$r||!hash_equals($r['source_hash'],(string)$in['resource_hash']))throw new Problem('Sursa s-a schimbat sau este protejată.',409);$payment=one($db,'SELECT p.* FROM payment_resolutions pr JOIN netopia_payments p ON p.id=pr.payment_id WHERE pr.invoice_id=?',[$d['invoice_id']]);$diff=$payment?(int)$payment['gross_amount_cents']-(int)$i['amount_cents']:null;if($diff!==null&&!in_array($diff,[0,1],true)&&($in['accept_difference']??false)!==true)throw new Problem('Confirmă explicit diferența de sumă față de factura curentă.');$id=decision($db,'source_reviewed',['invoice'=>$d['invoice_id'],'shipment'=>$d['shipment_id'],'payment'=>$payment['id']??$d['payment_id'],'order'=>$d['order_id']],['reviewed_change'=>$d['id'],'resource_hash'=>$r['source_hash'],'invoice_hash'=>$i['source_hash'],'payment_hash'=>$payment['source_hash']??null],$reason,$actor,'reviewed:'.bin2hex(random_bytes(20)),$diff);query($db,'UPDATE decisions SET active=0 WHERE id=?',[$d['id']]);query($db,'UPDATE decisions SET supersedes_decision_id=? WHERE id=?',[$d['id'],$id]);return ['saved'=>true];});}
 static function refund(\PDO $db,array $in,array $actor):array {
  permit($actor,'operate');$request=(string)($in['request_key']??'');if(strlen($request)<12||strlen($request)>190)throw new Problem('Cheie de salvare invalidă.');$key='refund:'.hash('sha256',$actor['id'].':'.$request);$intent=$in;unset($intent['request_key']);$intentHash=hashSource($intent);
  return transaction($db,function()use($db,$in,$actor,$key,$intentHash){
   $s=one($db,'SELECT * FROM fan_shipments WHERE id=? FOR UPDATE',[(int)($in['shipment']??0)]);if(!$s||$s['delivery_status']!=='returned'||method($s)!=='NETOPIA')throw new Problem('Returul nu este NETOPIA.');
   if(one($db,"SELECT id FROM decisions WHERE shipment_id=? AND action='return_redelivered' AND active=1",[$s['id']]))throw new Problem('Coletul a fost relivrat cu alt AWB; restituirea nu este necesară.');$p=one($db,'SELECT * FROM netopia_payments WHERE id=? FOR UPDATE',[(int)($in['payment']??0)]);$old=one($db,'SELECT id,source_hashes_json FROM decisions WHERE idempotency_key=?',[$key]);if($old){if((json_decode($old['source_hashes_json'],true)['request_hash']??'')!==$intentHash)throw new Problem('Cheie reutilizată pentru altă restituire.',409);return ['saved'=>true,'repeated'=>true,'decision'=>$old['id']];}
   if(!$p||!hash_equals($p['source_hash'],(string)($in['resource_hash']??''))||!hash_equals($s['source_hash'],(string)($in['shipment_hash']??'')))throw new Problem('Plata sau returul s-a schimbat.',409);
   $sameInvoice=one($db,'SELECT a.invoice_id FROM shipment_assignments a JOIN payment_resolutions pr ON pr.invoice_id=a.invoice_id WHERE a.shipment_id=? AND pr.payment_id=?',[$s['id'],$p['id']]);$sameOrder=$s['order_reference']&&one($db,"SELECT payment_id FROM payment_identifiers WHERE provider='NETOPIA' AND status='approved' AND external_id=? AND payment_id=?",[$s['order_reference'],$p['id']]);if(!$sameInvoice&&!$sameOrder)throw new Problem('Nu există o legătură verificată între retur și plată.');
   $amount=$in['amount']??null;$ref=trim((string)($in['reference']??''));if(!is_int($amount)||$amount<=0||!validDate($in['date']??null)||$in['date']>date('Y-m-d')||mb_strlen($ref)<3||mb_strlen($ref)>190)throw new Problem('Completează suma pozitivă, data și referința restituirii.');
   $prior=(int)query($db,'SELECT COALESCE(SUM(refund_amount_cents),0) FROM refunds WHERE payment_id=?',[$p['id']])->fetchColumn();if($prior+$amount>(int)$p['gross_amount_cents'])throw new Problem('Restituirile cumulate depășesc suma achitată.');if(one($db,'SELECT id FROM refunds WHERE payment_id=? AND reference=? AND refund_date=?',[$p['id'],$ref,$in['date']]))throw new Problem('Această referință de restituire este deja înregistrată.',409);
   $reason=self::reason($in);$did=decision($db,'refund_reported',['payment'=>$p['id'],'shipment'=>$s['id']],['request_hash'=>$intentHash,'resource_hash'=>$p['source_hash'],'shipment_hash'=>$s['source_hash'],'amount'=>$amount,'date'=>$in['date'],'reference'=>$ref],$reason,$actor,$key);
   $ret=one($db,'SELECT id,payment_id FROM shipment_returns WHERE shipment_id=? FOR UPDATE',[$s['id']]);if($ret&&$ret['payment_id']&&(int)$ret['payment_id']!==(int)$p['id'])throw new Problem('Returul are deja altă plată asociată.');$status=$prior+$amount===(int)$p['gross_amount_cents']?'refund_reported':'partial_refund_reported';
   if($ret){$rid=$ret['id'];query($db,'UPDATE shipment_returns SET payment_id=?,status=?,decision_id=? WHERE id=?',[$p['id'],$status,$did,$rid]);}else{query($db,'INSERT INTO shipment_returns(shipment_id,payment_id,status,decision_id) VALUES(?,?,?,?)',[$s['id'],$p['id'],$status,$did]);$rid=(int)$db->lastInsertId();}
   query($db,"INSERT INTO refunds(return_id,payment_id,refund_amount_cents,refund_date,reference,evidence_type,decision_id) VALUES(?,?,?,?,?,'user_reported',?)",[$rid,$p['id'],$amount,$in['date'],$ref,$did]);if(!one($db,'SELECT payment_id FROM payment_resolutions WHERE payment_id=?',[$p['id']]))query($db,"INSERT INTO payment_resolutions(payment_id,resolution,decision_id) VALUES(?,'refunded_user_reported',?)",[$p['id'],$did]);audit($db,'refund_reported',['return'=>$rid,'payment'=>$p['id'],'amount'=>$amount],$actor,$did);return ['saved'=>true,'decision'=>$did,'status'=>$status];
  });
 }
 static function reason(array $input):string{$s=trim((string)($input['reason']??''));if(mb_strlen($s)<10||mb_strlen($s)>1000)throw new Problem('Motiv obligatoriu, 10–1000 caractere.');return $s;}
 static function correct(\PDO $db,array $in,array $actor):array {
  permit($actor,'admin');$reason=self::reason($in);$mode=$in['mode']??'';if(!in_array($mode,['revoke','reconsider'],true))throw new Problem('Corecție invalidă.');
  return transaction($db,function()use($db,$in,$actor,$reason,$mode){
   $d=one($db,'SELECT * FROM decisions WHERE id=? FOR UPDATE',[(int)($in['id']??0)]);if(!$d||!(int)$d['active'])throw new Problem('Decizia nu mai este activă. Reîncarcă.',409);
   $kind=$d['payment_id']?'netopia':($d['shipment_id']?'fan':($d['order_id']?'site':null));if(!$kind)throw new Problem('Acest tip de decizie are un flux separat.');
   $col=['netopia'=>'payment_id','fan'=>'shipment_id','site'=>'order_id'][$kind];$resource=(int)$d[$col];$r=one($db,'SELECT * FROM '.Store::TABLE[$kind].' WHERE id=? FOR UPDATE',[$resource]);if(!$r||!hash_equals($r['source_hash'],(string)($in['resource_hash']??'')))throw new Problem('Sursa s-a schimbat.',409);
   if($d['invoice_id']){$invoice=one($db,'SELECT * FROM invoices WHERE id=? FOR UPDATE',[$d['invoice_id']]);if(!$invoice||$invoice['scope']==='internal')throw new Problem('Document protejat.');}
   if($mode==='reconsider'){if(!in_array($d['action'],['rejected','revoked'],true))throw new Problem('Se pot reconsidera numai respingeri sau blocări după revocare.');}
   elseif($d['action']==='netopia_allocated'){query($db,"UPDATE decisions SET active=0 WHERE payment_id=? AND action='netopia_allocation' AND active=1",[$resource]);}
   elseif(in_array($d['action'],['netopia_topup','netopia_return_review','netopia_return_partial_review'],true)){if(one($db,'SELECT id FROM refunds WHERE payment_id=?',[$resource]))throw new Problem('Plata suplimentară are restituiri.');}
   else {
    if($kind==='netopia'&&$d['invoice_id']&&Topups::rows($db,(int)$d['invoice_id']))throw new Problem('Revocă mai întâi plățile suplimentare ale facturii.');
    if(!in_array($d['action'],['confirmed','link_order','closed_user_reported','refunded_user_reported'],true))throw new Problem('Decizia nu reprezintă o asociere sau închidere revocabilă.');
    if($kind==='netopia'&&(one($db,'SELECT id FROM refunds WHERE payment_id=?',[$resource])||one($db,'SELECT id FROM shipment_returns WHERE payment_id=?',[$resource])))throw new Problem('Plata are dovezi de restituire. Nu se eliberează prin revocarea asocierii.');
    if($kind==='fan'&&one($db,'SELECT id FROM shipment_returns WHERE shipment_id=?',[$resource]))throw new Problem('AWB-ul are o restituire înregistrată.');
    if($kind!=='site'&&$d['invoice_id']&&one($db,'SELECT id FROM cash_circuits WHERE original_invoice_id=? AND status=\'confirmed\'',[$d['invoice_id']]))throw new Problem('Factura face parte dintr-un circuit numerar confirmat.');
    $table=['netopia'=>'payment_resolutions','fan'=>'shipment_assignments','site'=>'invoice_orders'][$kind];$link=one($db,'SELECT * FROM '.$table.' WHERE '.$col.'=? FOR UPDATE',[$resource]);if(!$link||(int)$link['decision_id']!==(int)$d['id'])throw new Problem('Legătura actuală nu mai aparține acestei decizii.',409);
    if($kind==='site'&&one($db,'SELECT id FROM gpd_deliveries WHERE order_id=? AND invoice_id IS NULL',[$resource]))throw new Problem('Comanda are o livrare GPD atașată; verifică mai întâi livrarea.');
    query($db,'DELETE FROM '.$table.' WHERE '.$col.'=? AND decision_id=?',[$resource,$d['id']]);
   }
   $id=decision($db,$mode==='revoke'?'revoked':'reconsidered',['invoice'=>$d['invoice_id'],'payment'=>$d['payment_id'],'shipment'=>$d['shipment_id'],'order'=>$d['order_id']],['previous_decision'=>$d,'resource_hash'=>$r['source_hash']],$reason,$actor,'correction:'.bin2hex(random_bytes(20)));
   query($db,'UPDATE decisions SET active=0 WHERE id=?',[$d['id']]);query($db,'UPDATE decisions SET supersedes_decision_id=? WHERE id=?',[$d['id'],$id]);audit($db,'decision_'.$mode,['previous'=>$d['id'],'replacement'=>$id],$actor,$id);return ['saved'=>true,'decision'=>$id,'on_hold'=>$mode==='revoke'];
  });
 }
 static function history(\PDO $db,string $kind,int $id):array {
  if(!isset(Store::TABLE[$kind]))throw new Problem('Tip invalid.');$r=one($db,'SELECT * FROM '.Store::TABLE[$kind].' WHERE id=?',[$id]);if(!$r||($kind==='omc'&&$r['scope']==='internal'))throw new Problem('Documentul nu este accesibil.',404);
  $key=$r[Store::KEY[$kind]];$col=['omc'=>'invoice_id','netopia'=>'payment_id','fan'=>'shipment_id','site'=>'order_id'][$kind];$legacy=['omc'=>'invoice','netopia'=>'payment','fan'=>'shipment','site'=>'order'][$kind];
  $versions=query($db,'SELECT source_type,revision,source_json,content_hash,recorded_at FROM source_versions WHERE source_key=? AND source_type IN (?,?) ORDER BY recorded_at DESC,id DESC LIMIT 100',[$key,$kind,'legacy:'.$legacy])->fetchAll();
  foreach($versions as &$v){$v['data']=json_decode($v['source_json'],true);unset($v['source_json']);if($kind==='omc'&&nameKey($v['data']['client']??'')===nameKey('SUSEANU MARIAN'))$v['data']=['protected'=>true];}unset($v);
  $decisions=query($db,'SELECT id,action,active,reason,accepted_difference_cents,created_at,supersedes_decision_id,COALESCE((SELECT display_name FROM users WHERE id=actor_id),legacy_actor) AS actor FROM decisions WHERE '.$col.'=? ORDER BY id DESC LIMIT 100',[$id])->fetchAll();
  return ['resource'=>$r,'kind'=>$kind,'versions'=>$versions,'decisions'=>$decisions];
 }
 static function legacyBatches(\PDO $db,array $actor):array {
  $where=$actor['role']==='admin'?'1=1':'actor_id=?';$args=$actor['role']==='admin'?[]:[$actor['id']];$rows=query($db,"SELECT id,actor_id,revision,result_json FROM review_batches WHERE status='legacy_draft' AND ".$where.' ORDER BY id',$args)->fetchAll();
  foreach($rows as &$r){$r['legacy']=json_decode($r['result_json'],true);$r['items']=[];foreach($r['legacy']['payload'] as $item){$map=one($db,"SELECT target_table,target_id FROM migration_map WHERE legacy_table='v3_documents' AND legacy_key=? ORDER BY id DESC LIMIT 1",[(string)($item['resource_id']??'')]);$kind=$map?array_search($map['target_table'],Store::TABLE,true):false;if(!$kind||$kind==='omc'){ $r['items'][]=['unavailable'=>true,'action'=>$item['action']??'deferred'];continue;}$resource=one($db,'SELECT * FROM '.Store::TABLE[$kind].' WHERE id=?',[$map['target_id']]);$invoice=null;if($item['invoice_id']??null){$im=one($db,"SELECT target_id FROM migration_map WHERE legacy_table='v3_documents' AND target_table='invoices' AND legacy_key=? ORDER BY id DESC LIMIT 1",[(string)$item['invoice_id']]);if($im)$invoice=one($db,"SELECT * FROM invoices WHERE id=? AND scope<>'internal'",[$im['target_id']]);}$r['items'][]=['kind'=>$kind,'resource'=>$resource,'invoice'=>$invoice,'action'=>$item['action']??'deferred','reason'=>$item['reason']??'','unavailable'=>!$resource||(in_array($item['action']??'',['confirmed','rejected'],true)&&!$invoice)];}unset($r['result_json'],$r['legacy']['payload']);}unset($r);return $rows;
 }
 static function legacyResolve(\PDO $db,array $in,array $actor):array {
  permit($actor,'operate');$reason=self::reason($in);
  return transaction($db,function()use($db,$in,$actor,$reason){$b=one($db,"SELECT * FROM review_batches WHERE id=? AND status='legacy_draft' FOR UPDATE",[(int)$in['id']]);if(!$b||($actor['role']!=='admin'&&(int)$b['actor_id']!==(int)$actor['id']))throw new Problem('Lot istoric inaccesibil.');if((int)$b['revision']!==(int)$in['revision'])throw new Problem('Lotul s-a schimbat.',409);
   // The operator selects current sources through the ordinary review service.
   // The immutable legacy payload remains in result_json, even after archiving.
   if(($in['mode']??'')!=='archive')throw new Problem('Revalidează selecțiile în lotul curent, apoi arhivează lotul istoric.');query($db,"UPDATE review_batches SET status='legacy_reviewed',revision=revision+1 WHERE id=?",[$b['id']]);audit($db,'legacy_batch_reviewed',['id'=>$b['id'],'reason'=>$reason,'legacy_payload'=>json_decode($b['result_json'],true)],$actor);return ['saved'=>true];});
 }
 static function cashPlan(\PDO $db):array {
  $all=query($db,'SELECT * FROM invoices')->fetchAll();$byNumber=array_column($all,null,'invoice_number');$byId=array_column($all,null,'id');$internal=[];$stornos=[];
  foreach($all as $r){if($r['amount_cents']>0&&nameKey($r['client'])===nameKey('SUSEANU MARIAN'))$internal[]=$r;if($r['amount_cents']<0)$stornos[]=$r;}
  $used=[];foreach(query($db,'SELECT * FROM cash_circuits WHERE status=\'confirmed\'')->fetchAll() as $c)foreach(['original_invoice_id','storno_invoice_id','reissued_invoice_id'] as $col)$used[(int)$c[$col]]=true;
  $edges=[];$counts=[];foreach($stornos as $s){$sr=reference($s['observation']);if($sr['kind']!=='invoice'||!isset($byNumber[$sr['id']]))continue;$o=$byNumber[$sr['id']];if($o['amount_cents']<=0||$o['scope']==='internal'||(int)$o['amount_cents']!==-(int)$s['amount_cents']||$o['normalized_name']!==$s['normalized_name']||!validDate($o['invoice_date'])||!validDate($s['invoice_date'])||$s['invoice_date']<$o['invoice_date'])continue;
   foreach($internal as $r){$rr=reference($r['observation']);if($rr['kind']!=='invoice'||!in_array($rr['id'],[$o['invoice_number'],$s['invoice_number']],true)||!validDate($r['invoice_date'])||$r['invoice_date']<$s['invoice_date']||(int)$r['amount_cents']!==(int)$o['amount_cents'])continue;
    $ids=[(int)$o['id'],(int)$s['id'],(int)$r['id']];if(count(array_unique($ids))!==3||array_intersect($ids,array_keys($used)))continue;
    $order=reference($o['observation']);$financial=one($db,'SELECT shipment_id FROM shipment_assignments WHERE invoice_id=?',[$o['id']])||one($db,'SELECT payment_id FROM payment_resolutions WHERE invoice_id=?',[$o['id']]);
    if(!$financial)$financial=one($db,'SELECT id FROM netopia_payments WHERE normalized_name=? AND ABS(gross_amount_cents-?)<=1',[$o['normalized_name'],$o['amount_cents']]);
    if(!$financial)$financial=one($db,'SELECT id FROM fan_shipments WHERE normalized_name=? AND (cash_due_cents=0 OR cash_due_cents IS NULL OR ABS(cash_due_cents-?)<=1)',[$o['normalized_name'],$o['amount_cents']]);
    if(!$financial&&$order['kind']==='order')$financial=one($db,'SELECT id FROM fan_shipments WHERE order_reference=?',[$order['id']])||one($db,"SELECT payment_id FROM payment_identifiers WHERE status='approved' AND external_id=?",[$order['id']]);
    if(!$financial)$financial=one($db,"SELECT invoice_id FROM invoice_preferences WHERE invoice_id=? AND payment_method IN('FAN','NETOPIA')",[$o['id']]);
    if(!$financial)$financial=one($db,"SELECT l.order_id FROM invoice_orders l JOIN site_orders so ON so.id=l.order_id WHERE l.invoice_id=? AND (so.awb IS NOT NULL OR so.payment_method='Plata online - NETOPIA Payments')",[$o['id']]);
    if(!$financial&&$order['kind']==='order')$financial=one($db,"SELECT id FROM site_orders WHERE order_number=? AND (awb IS NOT NULL OR payment_method='Plata online - NETOPIA Payments')",[$order['id']]);
    if($financial)continue;$edge=['original'=>$o,'storno'=>$s,'reissued'=>$r];$edges[]=$edge;foreach($ids as $id)$counts[$id]=($counts[$id]??0)+1;
   }
  }
  return array_values(array_filter($edges,fn($e)=>$counts[$e['original']['id']]===1&&$counts[$e['storno']['id']]===1&&$counts[$e['reissued']['id']]===1));
 }
 static function cashApply(\PDO $db,array $actor,?array $input=null):array {
  permit($actor,'operate');return transaction($db,function()use($db,$actor,$input){$saved=0;$plan=self::cashPlan($db);foreach($plan as $e){if($input&&(int)$input['invoice']!==(int)$e['original']['id'])continue;$ids=array_map(fn($x)=>(int)$x['id'],$e);sort($ids);foreach($ids as $id){$locked=one($db,'SELECT source_hash FROM invoices WHERE id=? FOR UPDATE',[$id]);foreach($e as $source)if((int)$source['id']===$id&&!hash_equals($source['source_hash'],$locked['source_hash']))throw new Problem('Sursa circuitului s-a schimbat.',409);}$fresh=self::cashPlan($db);$found=false;foreach($fresh as $f)if((int)$f['original']['id']===(int)$e['original']['id']&&(int)$f['storno']['id']===(int)$e['storno']['id']&&(int)$f['reissued']['id']===(int)$e['reissued']['id']){$e=$f;$found=true;break;}if(!$found)throw new Problem('Circuitul numerar s-a schimbat.',409);
    $original=$e['original'];if(one($db,'SELECT payment_id FROM payment_resolutions WHERE invoice_id=? FOR UPDATE',[$original['id']])||one($db,'SELECT shipment_id FROM shipment_assignments WHERE invoice_id=? FOR UPDATE',[$original['id']])||one($db,'SELECT id FROM netopia_payments WHERE normalized_name=? AND ABS(gross_amount_cents-?)<=1 FOR UPDATE',[$original['normalized_name'],$original['amount_cents']])||one($db,'SELECT id FROM fan_shipments WHERE normalized_name=? AND (cash_due_cents IS NULL OR cash_due_cents=0 OR ABS(cash_due_cents-?)<=1) FOR UPDATE',[$original['normalized_name'],$original['amount_cents']]))throw new Problem('A apărut o dovadă FAN/NETOPIA; circuitul cere verificare.',409);if($input&&(!hash_equals($e['original']['source_hash'],(string)$input['source_hash'])))throw new Problem('Factura s-a schimbat.',409);$proof=[];foreach($e as $k=>$r)$proof[$k]=['id'=>$r['id'],'source_hash'=>$r['source_hash'],'amount_cents'=>$r['amount_cents']];$reason=$input?self::reason($input):'Circuit GPD numerar unic: referințe explicite, storno integral și refactură internă, fără dovezi FAN/NETOPIA.';$did=decision($db,'gpd_cash',['invoice'=>$e['original']['id']],$proof,$reason,$actor,'cash:'.hash('sha256',json($proof)));query($db,"INSERT INTO cash_circuits(original_invoice_id,storno_invoice_id,reissued_invoice_id,status,decision_id) VALUES(?,?,?,'confirmed',?)",[$e['original']['id'],$e['storno']['id'],$e['reissued']['id'],$did]);query($db,"INSERT INTO invoice_preferences(invoice_id,payment_method,reason,decision_id) VALUES(?,'GPD',?,?) ON DUPLICATE KEY UPDATE payment_method='GPD',reason=VALUES(reason),decision_id=VALUES(decision_id)",[$e['original']['id'],$reason,$did]);audit($db,'cash_circuit_confirmed',['invoice'=>$e['original']['invoice_number']],$actor,$did);$saved++;}if($input&&!$saved)throw new Problem('Circuitul nu mai este eligibil. Reîncarcă verificarea.',409);return ['saved'=>$saved];});
 }
 static function cashCases(\PDO $db):array {$out=[];foreach(self::cashPlan($db) as $e)$out[]=['invoice'=>$e['original']['id'],'number'=>$e['original']['invoice_number'],'client'=>$e['original']['client'],'amount_cents'=>$e['original']['amount_cents'],'storno'=>$e['storno']['invoice_number'],'reissued'=>$e['reissued']['invoice_number'],'source_hash'=>$e['original']['source_hash']];return ['proposals'=>$out,'confirmed'=>(int)query($db,"SELECT COUNT(*) FROM cash_circuits WHERE status='confirmed'")->fetchColumn()];}
